select jsonb_pretty(jsonb_build_object(
'version_exists',to_regclass('public.paypal_schema_version') is not null,
'columns',(select jsonb_agg(column_name order by column_name) from information_schema.columns where table_schema='public' and table_name='pagos' and column_name in ('paypal_order_id','paypal_capture_id','respuesta_proveedor')),
'private_tables',(select jsonb_agg(jsonb_build_object('name',relname,'rls',relrowsecurity,'anon_select',has_table_privilege('anon',oid,'SELECT'),'authenticated_select',has_table_privilege('authenticated',oid,'SELECT'))) from pg_class where relnamespace='public'::regnamespace and relname in ('paypal_schema_version','paypal_checkouts','paypal_checkout_items','paypal_cart_imports')),
'check',(select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.pagos'::regclass and conname='chk_metodo_pago'),
'indexes',(select jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef)) from pg_indexes where schemaname='public' and indexname in ('pagos_paypal_order_unique','pagos_paypal_capture_unique','carritos_usuario_paypal_unique','carrito_producto_paypal_unique','paypal_one_active_checkout')),
'triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid))) from pg_trigger where not tgisinternal and tgrelid in ('public.pagos'::regclass,'public.ordenes'::regclass,'public.orden_detalle'::regclass,'public.biblioteca'::regclass,'public.auditoria_pagos'::regclass,to_regclass('public.paypal_checkouts'),to_regclass('public.paypal_checkout_items'),to_regclass('public.paypal_cart_imports'))),
'financial_grants',(select jsonb_agg(jsonb_build_object('table',t,'anon_insert',has_table_privilege('anon','public.'||t,'INSERT'),'authenticated_insert',has_table_privilege('authenticated','public.'||t,'INSERT'),'authenticated_update',has_table_privilege('authenticated','public.'||t,'UPDATE'),'authenticated_delete',has_table_privilege('authenticated','public.'||t,'DELETE'))) from unnest(array['ordenes','orden_detalle','pagos','biblioteca','auditoria_pagos'])t),
'admin_policies',(select jsonb_agg(jsonb_build_object('table',tablename,'qual',qual,'command',cmd)) from pg_policies where schemaname='public' and policyname='jjc_paypal_admin_read')
))